import{_ as e,H as l,f as i,i as a}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"Q83 | 架构：如何设计多Agent架构？","description":"","frontmatter":{},"headers":[],"relativePath":"致程序员：AI百问百答/Q83｜架构：如何设计多Agent架构？.md","filePath":"致程序员：AI百问百答/Q83｜架构：如何设计多Agent架构？.md","lastUpdated":1795559851000}'),n={name:"致程序员：AI百问百答/Q83｜架构：如何设计多Agent架构？.md"};function o(p,t,s,r,A,_){return l(),i("div",null,[...t[0]||(t[0]=[a('<h1 id="q83-架构-如何设计多agent架构" tabindex="-1">Q83 | 架构：如何设计多Agent架构？ <a class="header-anchor" href="#q83-架构-如何设计多agent架构" aria-label="Permalink to &quot;Q83 | 架构：如何设计多Agent架构？&quot;">​</a></h1><ul><li>作者介绍：彭靖田，Google Developers Expert</li></ul><p>Q：如何设计多 Agent 架构？</p><p>彭靖田：多 Agent 架构设计核心在于任务分工、消息调度、上下文管理。这里推荐一个简洁清晰的五步设计模板：</p><ol><li>确定 Agent 类型（按职责分工）a. 用户代理：接收用户请求</li></ol><ul><li><p>b. 规划 Agent：任务分解与分配</p></li><li><p>c. 专家 Agent：领域任务执行</p></li><li><p>d. 总结 Agent：结果整合输出</p></li></ul><ol start="2"><li>定义 Agent 间通信机制a. 顺序协作：线性流程调用</li></ol><ul><li><p>b. 协商协作：自主讨论投票</p></li><li><p>c. 调度器协调：中控路由管理</p></li></ul><ol start="3"><li>共享上下文管理a. 状态记录：任务状态 / 工具结果</li></ol><ul><li>b. 历史压缩：摘要防上下文污染</li></ul><ol start="4"><li>任务分配策略a. 静态路由：基于关键词分配</li></ol><ul><li>b. 动态规划：LLM 实时决策分配</li></ul><ol start="5"><li>执行与容错机制a. 重试机制：单 Agent 容错</li></ol><ul><li>b. 输出验证：结果完整性校验</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%B4%E7%A8%8B%E5%BA%8F%E5%91%98%EF%BC%9AAI%E7%99%BE%E9%97%AE%E7%99%BE%E7%AD%94/images/Q83/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E8%87%B4%E7%A8%8B%E5%BA%8F%E5%91%98%EF%BC%9AAI%E7%99%BE%E9%97%AE%E7%99%BE%E7%AD%94/images/Q83/1.png" alt=""></a></p><p>框架推荐</p><ul><li><p>AutoGen（强协作流程）</p></li><li><p>CrewAI（轻量 Agent 协作）</p></li><li><p>LangGraph（灵活、强状态管理、适合自定义）</p></li></ul>',17)])])}const E=e(n,[["render",o]]);export{u as __pageData,E as default};
